#!/usr/bin/env python3
"""Generate the Unity port's C# ID tables from Src/Autogenerated/*.h(pp).

The C++ headers stay the source of truth; re-run after regenerating them:
    python3 tools/unity/gen_ids.py
"""
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SRC = ROOT / 'Src' / 'Autogenerated'
OUT = ROOT / 'Unity' / 'Assets' / 'CastleFrenzy' / 'Scripts' / 'Autogenerated'

HEADER = '// Generated by tools/unity/gen_ids.py from Src/Autogenerated. Do not edit.\n'


def defines(path):
    for line in path.read_text(encoding='latin-1').splitlines():
        m = re.match(r'^\s*#define\s+([A-Za-z_][A-Za-z0-9_]*)\s+(-?\d+)\s*$', line)
        if m:
            yield m.group(1), int(m.group(2))


def write_class(name, entries, comment):
    body = ''.join(f'        public const int {k} = {v};\n' for k, v in entries)
    text = (HEADER + f'// {comment}\nnamespace CastleFrenzy\n{{\n    public static partial class Ids\n    {{\n'
            + body + '    }\n}\n')
    (OUT / f'{name}.cs').write_text(text, encoding='utf-8')


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    for header in ('Menu.h', 'Ingame.h', 'Fonts.h', 'Common.h', 'sounds.h'):
        entries = list(defines(SRC / header))
        write_class('Ids_' + header.split('.')[0], entries, header)
    strings = []
    for line in (SRC / 'FortressDefender_ID.hpp').read_text(encoding='latin-1').splitlines():
        m = re.match(r'^\s*STRING_\(\s*(\d+),\s*([A-Za-z_0-9]+)\s*\);', line)
        if m:
            strings.append((m.group(2), int(m.group(1))))
    body = ''.join(f'        public const int {k} = {v};\n' for k, v in strings)
    sids = ''.join(f'            {{ "{k}", {v} }},\n' for k, v in strings)
    text = (HEADER + 'using System.Collections.Generic;\n\nnamespace CastleFrenzy\n{\n'
            '    /// <summary>String table IDs (FortressDefender_ID.hpp).</summary>\n'
            '    public static class STRING_IDS\n    {\n' + body +
            f'        public const int COUNT = {len(strings)};\n\n'
            '        public static readonly Dictionary<string, int> BySid = new Dictionary<string, int>\n        {\n'
            + sids + '        };\n    }\n}\n')
    (OUT / 'StringIds.cs').write_text(text, encoding='utf-8')
    print('wrote', OUT)


if __name__ == '__main__':
    main()
